commands.command:
echo 'class AVLNode {
  constructor(key) {
    this.key = key;
    this.height = 1;
    this.left = null;
    this.right = null;
  }
}' > avl.js

echo '
class AVLTree {
  constructor() {
    this.root = null;
  }

  height(node) {
    return node ? node.height : 0;
  }

  balanceFactor(node) {
    return node ? this.height(node.right) - this.height(node.left) : 0;
  }

  updateHeight(node) {
    node.height = Math.max(this.height(node.left), this.height(node.right)) + 1;
  }
}' >> avl.js

echo '
  // Left rotation
  rotateLeft(x) {
    const y = x.right;
    const T2 = y.left;

    // Perform rotation
    y.left = x;
    x.right = T2;

    // Update heights
    this.updateHeight(x);
    this.updateHeight(y);

    // Return new root
    return y;
  }' >> avl.js

echo '
  // Right rotation
  rotateRight(y) {
    const x = y.left;
    const T2 = x.right;

    // Perform rotation
    x.right = y;
    y.left = T2;

    // Update heights
    this.updateHeight(y);
    this.updateHeight(x);

    // Return new root
    return x;
  }' >> avl.js

echo '
  // Insert a key into the tree
  insert(key) {
    this.root = this._insert(this.root, key);
  }

  _insert(node, key) {
    // Standard BST insert
    if (!node) return new AVLNode(key);

    if (key < node.key)
      node.left = this._insert(node.left, key);
    else if (key > node.key)
      node.right = this._insert(node.right, key);
    else // Duplicate keys not allowed
      return node;

    // Update height of current node
    this.updateHeight(node);

    // Get the balance factor
    const balance = this.balanceFactor(node);

    // Left Left Case
    if (balance < -1 && key < node.left.key)
      return this.rotateRight(node);

    // Right Right Case
    if (balance > 1 && key > node.right.key)
      return this.rotateLeft(node);

    // Left Right Case
    if (balance < -1 && key > node.left.key) {
      node.left = this.rotateLeft(node.left);
      return this.rotateRight(node);
    }

    // Right Left Case
    if (balance > 1 && key < node.right.key) {
      node.right = this.rotateRight(node.right);
      return this.rotateLeft(node);
    }

    // Return the unchanged node
    return node;
  }
}' >> avl.js
